}

impl<'t> Captures<'t> {
    pub fn start(&self) -> usize;              // byte offset of whole match
    pub fn end(&self) -> usize;
    pub fn as_str(&self) -> &'t str;           // whole match
    pub fn get(&self, i: usize) -> Option<&'t str>;  // capture group i (0 = whole)
