//! Minimal logging facility reproducing `env_logger`'s default output format:
//! `[2026-08-10T13:27:23Z INFO  marmite::site] message`.

use std::io::Write;
use std::sync::atomic::{AtomicU8, Ordering};

pub const ERROR: u8 = 1;
pub const WARN: u8 = 2;
pub const INFO: u8 = 3;
pub const DEBUG: u8 = 4;
pub const TRACE: u8 = 5;

static LEVEL: AtomicU8 = AtomicU8::new(WARN);

pub fn set_level(level: u8) {
    LEVEL.store(level, Ordering::Relaxed);
}

pub fn level() -> u8 {
    LEVEL.load(Ordering::Relaxed)
}

pub fn enabled(level: u8) -> bool {
    level <= LEVEL.load(Ordering::Relaxed)
}

fn level_name(level: u8) -> &'static str {
    match level {
        ERROR => "ERROR",
        WARN => "WARN ",
        INFO => "INFO ",
        DEBUG => "DEBUG",
        _ => "TRACE",
    }
}

pub fn log(level: u8, target: &str, message: &str) {
    if !enabled(level) {
        return;
    }
    let now = crate::date::now(0);
    let ts = format!(
        "{:04}-{:02}-{:02}T{:02}:{:02}:{:02}Z",
        now.year, now.month, now.day, now.hour, now.minute, now.second
    );
    let mut stderr = std::io::stderr().lock();
    let _ = writeln!(stderr, "[{} {} {}] {}", ts, level_name(level), target, message);
}

#[macro_export]
macro_rules! log_at {
    ($level:expr, $target:expr, $($arg:tt)*) => {
        if $crate::logger::enabled($level) {
            $crate::logger::log($level, $target, &format!($($arg)*));
        }
    };
}

#[macro_export]
macro_rules! info {
    ($target:expr, $($arg:tt)*) => { $crate::log_at!($crate::logger::INFO, $target, $($arg)*) };
}

#[macro_export]
macro_rules! warn {
    ($target:expr, $($arg:tt)*) => { $crate::log_at!($crate::logger::WARN, $target, $($arg)*) };
}

#[macro_export]
macro_rules! error {
    ($target:expr, $($arg:tt)*) => { $crate::log_at!($crate::logger::ERROR, $target, $($arg)*) };
}

#[macro_export]
macro_rules! debug {
    ($target:expr, $($arg:tt)*) => { $crate::log_at!($crate::logger::DEBUG, $target, $($arg)*) };
}

#[macro_export]
macro_rules! trace {
    ($target:expr, $($arg:tt)*) => { $crate::log_at!($crate::logger::TRACE, $target, $($arg)*) };
}

//! Civil date/time handling: parsing, arithmetic and `strftime` formatting.
//!
//! Only the pieces the site generator needs are implemented, but the
//! `strftime` specifier set mirrors chrono's so templates behave the same.

use std::cmp::Ordering;
use std::fmt::Write as _;

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct DateTime {
    pub year: i32,
    pub month: u32,
    pub day: u32,
    pub hour: u32,
    pub minute: u32,
    pub second: u32,
    pub nanos: u32,
    /// Offset from UTC in seconds.
    pub offset: i32,
}

impl PartialOrd for DateTime {
    fn partial_cmp(&self, other: &Self) -> Option<Ordering> {
        Some(self.cmp(other))
    }
}

impl Ord for DateTime {
    fn cmp(&self, other: &Self) -> Ordering {
        self.timestamp()
            .cmp(&other.timestamp())
            .then(self.nanos.cmp(&other.nanos))
    }
}

