//! Template tests (`x is defined`, `x is starting_with("y")`, ...).

use super::eval::{msg, Error};
use crate::value::Value;

pub fn run(name: &str, value: Option<&Value>, args: &[Value]) -> Result<bool, Error> {
    match name {
        "defined" => return Ok(value.is_some()),
        "undefined" => return Ok(value.is_none()),
        _ => {}
    }
    let Some(value) = value else {
        // Tera raises an error when testing an undefined variable with anything
        // other than `defined`/`undefined`.
        return msg(format!(
            "Tester `{name}` was called on an undefined variable"
        ));
    };
    let text = value.render();
    let result = match name {
        "string" => matches!(value, Value::Str(_)),
        "number" => matches!(value, Value::Int(_) | Value::Float(_)),
        "odd" => value.as_int().map_or(false, |i| i % 2 != 0),
        "even" => value.as_int().map_or(false, |i| i % 2 == 0),
        "divisibleby" => {
            let by = args.first().and_then(|v| v.as_int()).unwrap_or(1);
            by != 0 && value.as_int().map_or(false, |i| i % by == 0)
        }
        "iterable" => matches!(value, Value::Array(_) | Value::Map(_) | Value::Str(_)),
        "object" => matches!(value, Value::Map(_)),
        "empty" => match value {
            Value::Str(s) => s.is_empty(),
            Value::Array(a) => a.is_empty(),
            Value::Map(m) => m.is_empty(),
            Value::Null => true,
            _ => false,
        },
        "starting_with" => {
            let prefix = args.first().map(|v| v.render()).unwrap_or_default();
            text.starts_with(&prefix)
        }
        "ending_with" => {
            let suffix = args.first().map(|v| v.render()).unwrap_or_default();
            text.ends_with(&suffix)
        }
        "containing" => {
            let needle = args.first().cloned().unwrap_or(Value::Null);
            match value {
                Value::Str(s) => s.contains(&needle.render()),
                Value::Array(items) => items.iter().any(|i| i.render() == needle.render()),
                Value::Map(map) => map.contains_key(&needle.render()),
                _ => false,
            }
        }
        "matching" => {
            let pattern = args.first().map(|v| v.render()).unwrap_or_default();
            crate::regex::Regex::new(&pattern)
                .map(|re| re.is_match(&text))
                .unwrap_or(false)
        }
        other => return msg(format!("Tester `{other}` not found")),
    };
    Ok(result)
}
